/**
 * Golden-fixture parity test: every case in fixtures.json (generated by
 * scripts/gen_api_fixtures.py from the Python library) must match exactly,
 * with floats compared to 1e-4.
 *
 * Bundle location: $MUSIC_BUNDLE, else ../api_bundle relative to ts/.
 */
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { after, describe, test } from "node:test";
import { fileURLToPath } from "node:url";
import { MusicData, mulberry32, normalizeName, readNpy } from "../src/index.js";

const here = dirname(fileURLToPath(import.meta.url));
const bundle = process.env.MUSIC_BUNDLE ?? resolve(here, "..", "..", "api_bundle");
const fixtures: { function: string; args: any[]; expected: any }[] = JSON.parse(
  readFileSync(join(here, "fixtures.json"), "utf-8"),
);

const camel = (s: string) => s.replace(/_([a-z])/g, (_, c) => c.toUpperCase());

function plain(x: any): any {
  if (x instanceof Float32Array || x instanceof Float64Array) return Array.from(x);
  if (Array.isArray(x)) return x.map(plain);
  if (x && typeof x === "object") return Object.fromEntries(Object.entries(x).map(([k, v]) => [k, plain(v)]));
  return x;
}

function close(actual: any, expected: any, path: string): void {
  if (typeof expected === "number" && typeof actual === "number") {
    assert.ok(Math.abs(actual - expected) <= 1e-4, `${path}: ${actual} != ${expected}`);
  } else if (Array.isArray(expected)) {
    assert.ok(Array.isArray(actual), `${path}: expected array`);
    assert.equal(actual.length, expected.length, `${path}: length`);
    expected.forEach((e, i) => close(actual[i], e, `${path}[${i}]`));
  } else if (expected && typeof expected === "object") {
    assert.ok(actual && typeof actual === "object", `${path}: expected object, got ${actual}`);
    assert.deepEqual(Object.keys(actual).sort(), Object.keys(expected).sort(), `${path}: keys`);
    for (const k of Object.keys(expected)) close(actual[k], expected[k], `${path}.${k}`);
  } else {
    assert.equal(actual, expected, path);
  }
}

describe("golden fixtures", { skip: !existsSync(join(bundle, "music.db")) && "bundle not found" }, () => {
  const md = existsSync(join(bundle, "music.db")) ? new MusicData(bundle) : null;
  after(() => md?.close());

  for (const [i, fx] of fixtures.entries()) {
    test(`${i}: ${fx.function}(${JSON.stringify(fx.args).slice(0, 60)})`, () => {
      const fn = (md as any)[camel(fx.function)];
      assert.equal(typeof fn, "function", `missing ${camel(fx.function)}`);
      const got = plain(fn.apply(md, fx.args));
      close(got, fx.expected, fx.function);
    });
  }

  test("every public Python function has a fixture", () => {
    const covered = new Set(fixtures.map((f) => f.function));
    for (const f of [
      "search_artists", "get_artist", "get_artists", "get_artist_tracks", "similar_artists",
      "similarity_between", "nearest_to_vector", "get_vector", "list_genres", "artists_by_genre",
      "random_artists", "resolve_artist", "dataset_info",
    ]) assert.ok(covered.has(f), f);
  });

  test("unknown input never throws", async () => {
    const m = md!;
    assert.equal(m.getArtist(undefined as any), null);
    assert.deepEqual(m.similarArtists("x", "bogus" as any), []);
    assert.deepEqual(m.nearestToVector([NaN, 1], "audio"), []);
    assert.deepEqual(m.searchArtists(null as any), []);
    assert.equal(await m.getPreviewUrl(-1), null);
  });
});

test("helpers", () => {
  assert.equal(normalizeName("  Björk!! "), "bjork");
  const r = mulberry32(42);
  assert.deepEqual([r(), r(), r()].map((x) => x.toFixed(9)), ["0.601103752", "0.448290559", "0.852465793"]);
});

test("npy reader matches bundle manifest", { skip: !existsSync(join(bundle, "audio.f16.npy")) }, () => {
  const m = readNpy(join(bundle, "audio.f16.npy"));
  const manifest = JSON.parse(readFileSync(join(bundle, "manifest.json"), "utf-8"));
  assert.equal(m.rows, manifest.embeddings.audio.count);
  assert.equal(m.cols, 512);
});
